:root {
  --ink: #3d251d;
  --paper: #fff9ed;
  --orange: #e86e2d;
  --gold: #f8c45a;
  --line: #e6c89d;
}

* {
  box-sizing: border-box;
}

.pass {
  width: 460px;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 16px;
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: var(--orange);
  color: var(--paper);
}

.pass-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  background: var(--gold);
  border: 2px solid var(--ink);
  border-radius: 50%;
  font-size: 24px;
}

.eyebrow {
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.1;
}

.bench {
  margin-left: auto;
  padding: 6px 8px;
  background: var(--ink);
  border-radius: 7px;
  font-size: 13px;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  color: var(--ink);
  font-size: 14px;
  font-weight: 600;
}

button {
  padding: 6px 10px;
  background: var(--gold);
  border: 1px solid var(--ink);
  border-radius: 7px;
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}
